import type { NextConfig } from "next";
import { contentSecurityPolicy } from "./src/lib/security-headers";

const isDev = process.env.NODE_ENV !== "production";

const nextConfig: NextConfig = {
  experimental: {
    // The import dialog accepts 5 MB spreadsheets and sends the parsed rows
    // through a Server Action; the 1 MB default cuts large guest lists off.
    serverActions: {
      bodySizeLimit: '8mb',
    },
  },
  // The dev-only floating badge would leak into the README screenshots
  // generated by the Playwright suite.
  devIndicators: false,
  poweredByHeader: false,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  // Baseline headers plus a real CSP. `script-src` keeps 'unsafe-inline'
  // because Next ships inline bootstrap scripts; a nonce would remove it at the
  // cost of threading every render. See src/lib/security-headers.ts.
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=()",
          },
          {
            key: "Strict-Transport-Security",
            value: "max-age=31536000; includeSubDomains",
          },
          { key: "Content-Security-Policy", value: contentSecurityPolicy(isDev) },
        ],
      },
    ];
  },
};

export default nextConfig;
